import{_ as a,a0 as r,w as i,s as d,ao as l,I as u,x as t,a1 as e,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Linux有問必答——如何為sudo命令定義PATH環境變量 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答——如何為sudo命令定義PATH環境變量 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答——如何為sudo命令定義PATH環境變量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答——如何為sudo命令定義PATH環境變量 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140716 Linux FAQs with Answers--How to define PATH environment variable for sudo commands","title":"Linux有問必答——如何為sudo命令定義PATH環境變量","tag":"201409","desc":""},"relativePath":"201409/20140716 Linux FAQs with Answers--How to define PATH environment variable for sudo commands.md","filePath":"[post].md"}'),m={name:"201409/20140716 Linux FAQs with Answers--How to define PATH environment variable for sudo commands.md"};function p(T,o,f,A,x,_){const n=r("Link");return i(),d("div",null,[o[11]||(o[11]=l(`<h1 id="linux有問必答——如何為sudo命令定義path環境變量" tabindex="-1">Linux有問必答——如何為sudo命令定義PATH環境變量 <a class="header-anchor" href="#linux有問必答——如何為sudo命令定義path環境變量" aria-label="Permalink to “Linux有問必答——如何為sudo命令定義PATH環境變量”">​</a></h1><blockquote><p><strong>問題</strong>:我安裝了一個程序到/usr/local/bin目錄下，這個程序需要root權限才能執行，當我用sudo去執行它時，收到&quot;sudo: XXXXX: command not found&quot;的錯誤提示，不知道為什麼/usr/local/bin沒有被包含到PATH環境變量下面來，我該如何解決這個問題？</p></blockquote><p>當你使用sudo去執行一個程序時，處於安全的考慮，這個程序將在一個新的、最小化的環境中執行，也就是説，諸如PATH這樣的環境變量，在sudo命令下已經被重置成默認狀態了。所以當一個剛初始化的PATH變量中不包含你所要運行的程序所在的目錄，用sudo去執行，你就會得到&quot;command not found&quot;的錯誤提示。</p><p>要想改變PATH在sudo會話中的初始值，用文本編輯器打開/etc/sudoers文件，找到&quot;secure_path&quot;一行，當你執行sudo 命令時，&quot;secure_path&quot;中包含的路徑將被當做默認PATH變量使用。</p><p>添加所需要的路徑(如 /usr/local/bin）到&quot;secure_path&quot;下，在開篇所遇見的問題就將迎刃而解。</p><pre><code>Defaults    secure_path = /sbin:/bin:/usr/sbin:/usr/bin:/usr/local/bin
</code></pre><p>這個修改會即刻生效。</p><hr>`,8)),u("p",null,[o[1]||(o[1]=t("via: ",-1)),e(n,{href:"http://ask.xmodulo.com/define-path-environment-variable-sudo-commands.html"},{default:s(()=>[...o[0]||(o[0]=[t("http://ask.xmodulo.com/define-path-environment-variable-sudo-commands.html",-1)])]),_:1})]),u("p",null,[o[4]||(o[4]=t("譯者：",-1)),e(n,{href:"https://github.com/nd0104"},{default:s(()=>[...o[2]||(o[2]=[t("nd0104",-1)])]),_:1}),o[5]||(o[5]=t(" 校對：",-1)),e(n,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...o[3]||(o[3]=[t("Caroline",-1)])]),_:1})]),u("p",null,[o[8]||(o[8]=t("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...o[6]||(o[6]=[t("LCTT",-1)])]),_:1}),o[9]||(o[9]=t(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:s(()=>[...o[7]||(o[7]=[t("Linux中國",-1)])]),_:1}),o[10]||(o[10]=t(" 榮譽推出",-1))])])}const H=a(m,[["render",p]]);export{L as __pageData,H as default};
